import assert from "node:assert/strict";
import type { BrowserContext, Page } from "playwright-core";
import { OpSocket, waitFor } from "./harness.ts";

/**
 * Room sound for the e2e files (docs/design/design-v1-music.md 12): sound
 * files of silence built frame by frame, so nothing is recorded or
 * generated by a model, uploaded through the asset route and added with
 * `sound.create`, and the page's test hook (features/sound/engine/testHook.ts)
 * read back. sound.e2e.ts and soundpanel.e2e.ts share it.
 */

/** Set before the app's first script: the engine's test hook (testHook.ts SOUND_TEST_FLAG). */
export const SOUND_TEST_FLAG = "globalThis.__rvttSoundTest = true;";

/**
 * An iPhone's autoplay rules, set before the app's first script, for a
 * Chrome that would play without them. Chrome counts a touch pointerdown as
 * a user activation and lets a page that was tapped before keep playing
 * after a reload, where the HTML spec and Safari count only pointerup,
 * touchend, click and keys, and each page load starts locked. So here, as
 * rolls.e2e.ts does for the turn chime, an AudioContext
 * reads "suspended" until a resume() runs inside an event the spec counts,
 * a resume() outside one stays pending, and an audio element refuses to
 * play until it has played once inside such an event, which is what the
 * pool's blessing is for (docs/design/design-v1-music.md 5.5).
 */
export const IPHONE_AUDIO = `(() => {
  let counted = false;
  for (const type of ["pointerdown", "pointerup", "touchend", "click", "keydown"]) {
    addEventListener(type, (g) => {
      const spec = g.type === "pointerdown" ? g.pointerType === "mouse" : g.type === "pointerup" ? g.pointerType !== "mouse" : g.type === "keydown" ? g.key !== "Escape" : true;
      if (!spec) return;
      counted = true;
      setTimeout(() => (counted = false), 0);
    }, true);
  }
  const Real = globalThis.AudioContext;
  let owner = Real.prototype;
  while (owner && !Object.getOwnPropertyDescriptor(owner, "state")) owner = Object.getPrototypeOf(owner);
  const realState = Object.getOwnPropertyDescriptor(owner, "state").get;
  globalThis.AudioContext = class extends Real {
    constructor(...args) {
      super(...args);
      this.__unlocked = counted;
      Object.defineProperty(this, "state", { get: () => (this.__unlocked ? realState.call(this) : "suspended") });
    }
    resume() {
      if (!counted) return new Promise(() => {});
      const was = this.__unlocked;
      this.__unlocked = true;
      const done = super.resume();
      if (!was) queueMicrotask(() => this.dispatchEvent(new Event("statechange")));
      return done;
    }
  };
  const play = HTMLMediaElement.prototype.play;
  const blessed = new WeakSet();
  HTMLMediaElement.prototype.play = function () {
    if (counted) blessed.add(this);
    if (!blessed.has(this)) return Promise.reject(new DOMException("needs a tap", "NotAllowedError"));
    return play.call(this);
  };
})();`;

/** A member's Room sound chosen before the page loads, as Play here leaves it. */
export function roomSoundScript(choice: "on" | "off" | null): string {
  return choice === null ? "localStorage.removeItem('rvtt.roomSound');" : `localStorage.setItem('rvtt.roomSound', '${choice}');`;
}

/** 48 kHz needs no padding byte: 64 kbps frames are exactly 192 bytes, 24 ms each. */
const RATE = 48_000;
const FRAME_BYTES = 192;
const FRAME_MS = (1152 / RATE) * 1000;

/**
 * An MP3 of silence at least `ms` long: MPEG-1 Layer III, 48 kHz, 64 kbps,
 * mono, every frame a header and zeros, which decodes as silence (the same
 * frames as scripts/silence.ts at another rate). Its length is a whole
 * number of frames, as the server counts it.
 */
export function silentSound(ms: number): Buffer {
  const frames = Math.ceil(ms / FRAME_MS);
  const out = Buffer.alloc(frames * FRAME_BYTES);
  for (let i = 0; i < frames; i++) {
    const at = i * FRAME_BYTES;
    out[at] = 0xff;
    out[at + 1] = 0xfb;
    // 64 kbps, 48 kHz, no padding.
    out[at + 2] = (0b0101 << 4) | (0b01 << 2);
    // Mono.
    out[at + 3] = 0b11 << 6;
  }
  return out;
}

/** A sound's length as the server walks it: frames times 1152 over the rate, rounded down. */
export function silentMs(ms: number): number {
  return Math.floor((Math.ceil(ms / FRAME_MS) * 1152 * 1000) / RATE);
}

export type SoundRow = { id: string; audio?: { ms: number; channels: number; kbps: number } };

/** Uploads a sound file as the DM, through the asset route (`kind=sound`). */
export async function uploadSound(context: BrowserContext, origin: string, roomId: string, bytes: Buffer, name: string): Promise<SoundRow> {
  const res = await context.request.put(`${origin}/api/rooms/${roomId}/assets?kind=sound`, { headers: { Origin: origin, "content-type": "audio/mpeg", "x-name": name }, data: bytes });
  assert.ok(res.ok(), `the sound upload answered ${res.status()}: ${await res.text()}`);
  return (await res.json()) as SoundRow;
}

/** Uploads silence of `ms` and adds it to the room's library as `use`, returning the sound's id. */
export async function addSound(input: { context: BrowserContext; origin: string; roomId: string; ops: OpSocket; id: string; name: string; use: "music" | "loop" | "effect"; ms: number }): Promise<string> {
  const row = await uploadSound(input.context, input.origin, input.roomId, silentSound(input.ms), `${input.name}.mp3`);
  await input.ops.send({ t: "sound.create", id: input.id, assetId: row.id, name: input.name, use: input.use, ms: row.audio?.ms ?? silentMs(input.ms) });
  return input.id;
}

export type Voice = { key: string; sound: string; channel: "music" | "loop"; aimMs: number; currentMs: number; rate: number; playing: boolean };
export type SoundProbe = {
  data: string;
  voices: Voice[];
  effects: { playing: number; started: { id: string; at: number; offsetMs: number }[] };
  state: { owns: boolean; offset: number | null; lease: number; context: string; now: number | null } | null;
};

/** What a page's engine says now: `data-sound`, and the test hook's voices, effects and state. */
export function soundProbe(page: Page): Promise<SoundProbe> {
  return page.evaluate(() => {
    type Root = { dataset: Record<string, string | undefined>; soundVoices?: unknown; soundEffects?: unknown; soundState?: unknown };
    const root = (globalThis as unknown as { document: { documentElement: Root } }).document.documentElement;
    return {
      data: root.dataset.sound ?? "",
      voices: (root.soundVoices ?? []) as Voice[],
      effects: (root.soundEffects ?? { playing: 0, started: [] }) as SoundProbe["effects"],
      state: (root.soundState ?? null) as SoundProbe["state"],
    };
  });
}

/** Waits for `data-sound` to match. */
export async function soundSays(page: Page, pattern: RegExp, timeoutMs = 15_000): Promise<SoundProbe> {
  let last: SoundProbe | null = null;
  try {
    return await waitFor(
      `data-sound to match ${pattern}`,
      async () => {
        last = await soundProbe(page);
        return pattern.test(last.data) ? last : null;
      },
      timeoutMs,
    );
  } catch (err) {
    throw new Error(`${(err as Error).message}, and it said ${JSON.stringify(last)}`, { cause: err });
  }
}

/** The sounding music voice: the one whose aim is inside its file. */
export function musicVoice(probe: SoundProbe): Voice | undefined {
  return probe.voices.find((v) => v.channel === "music" && v.playing && v.aimMs >= 0);
}

/** How far each playing voice is from its aim, in ms. */
export function errors(probe: SoundProbe): number[] {
  return probe.voices.filter((v) => v.playing && v.aimMs >= 0).map((v) => Math.abs(v.currentMs - v.aimMs));
}

/** Waits until every playing voice of a page is within `ms` of its aim, and returns the probe. */
export async function inStep(page: Page, ms: number, timeoutMs = 8_000): Promise<SoundProbe> {
  let last: SoundProbe | null = null;
  try {
    return await waitFor(
      `every voice within ${ms} ms`,
      async () => {
        last = await soundProbe(page);
        const errs = errors(last);
        return errs.length > 0 && errs.every((e) => e <= ms) ? last : null;
      },
      timeoutMs,
    );
  } catch (err) {
    throw new Error(`${(err as Error).message}, and it said ${JSON.stringify(last)}`, { cause: err });
  }
}
